    function convertAmountToWords($amount)
    {
        $ones = [
            "", "One", "Two", "Three", "Four", "Five", "Six", "Seven",
            "Eight", "Nine", "Ten", "Eleven", "Twelve", "Thirteen",
            "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"
        ];

        $tens = [
            "", "", "Twenty", "Thirty", "Forty", "Fifty",
            "Sixty", "Seventy", "Eighty", "Ninety"
        ];

        $toWords = function ($num) use (&$toWords, $ones, $tens) {
            if ($num == 0) return "";

            $crore = floor($num / 10000000);
            $num -= $crore * 10000000;

            $lakh = floor($num / 100000);
            $num -= $lakh * 100000;

            $thousand = floor($num / 1000);
            $num -= $thousand * 1000;

            $hundred = floor($num / 100);
            $num -= $hundred * 100;

            $words = "";

            if ($crore)  $words .= $toWords($crore) . " Crore ";
            if ($lakh)   $words .= $toWords($lakh) . " Lakh ";
            if ($thousand) $words .= $toWords($thousand) . " Thousand ";
            if ($hundred)  $words .= $ones[$hundred] . " Hundred ";

            if ($num) {
                if ($num < 20) {
                    $words .= $ones[$num];
                } else {
                    $words .= $tens[floor($num / 10)] . " " . $ones[$num % 10];
                }
            }

            return trim($words);
        };

        $taka = floor($amount);
        $paisa = round(($amount - $taka) * 100);

        $result = "";
        if ($taka > 0) {
            $result .= $toWords($taka) . " Euro";
        } else {
            $result .= "Zero Euro";
        }

        if ($paisa > 0) {
            $result .= " and " . $toWords($paisa) . " Cent";
        }

        return trim($result . " Only.");
    }

    // Example usage:
   // echo convertAmountToWordsBD(12503450.75);
    // Output: One Crore Twenty Five Lakh Three Thousand Four Hundred Fifty Taka and Seventy Five Paisa Only.


@endphp

